<script>
  (function(){
    var selectedDay = 15;
    var selectedTime = null;
    var days = document.querySelectorAll('.day');
    var times = document.querySelectorAll('.time');
    var summary = document.getElementById('summary');
    var confirm = document.getElementById('confirm');

    days.forEach(function(d){
      if(d.classList.contains('out')) return;
      d.addEventListener('click', function(){
        days.forEach(function(x){ x.classList.remove('sel'); });
        d.classList.add('sel');
        selectedDay = parseInt(d.textContent, 10);
        updateSummary();
      });
    });

    times.forEach(function(t){
      t.addEventListener('click', function(){
        times.forEach(function(x){ x.classList.remove('active'); });
        t.classList.add('active');
        selectedTime = t.getAttribute('data-time');
        updateSummary();
      });
    });

    function updateSummary(){
      if(selectedTime){
        summary.textContent = 'الموعد: ' + selectedDay + ' سبتمبر 2025 الساعة ' + selectedTime;
        summary.classList.add('show');
        confirm.disabled = false;
      } else {
        summary.classList.remove('show');
        confirm.disabled = true;
      }
    }

    document.getElementById('cancel').addEventListener('click', function(){
      times.forEach(function(x){ x.classList.remove('active'); });
      selectedTime = null;
      updateSummary();
    });

    confirm.addEventListener('click', function(){
      if(!selectedTime) return;
      alert('تم تأكيد الحجز:\n' + selectedDay + ' سبتمبر 2025 - ' + selectedTime + '\nد. محمد الحمد');
    });
  })();
</script>
